(async()=>{
  const E=__echoes;
  const raf=()=>new Promise(r=>requestAnimationFrame(r));
  E.cmd('giveSkill','warding_aura');
  E.cmd('grantNode','ascend');
  E.cmd('openSocket');
  await raf();
  const cells=[...document.querySelectorAll('.nd-row')][0].querySelectorAll('.nd-cell');
  const cell=cells[0];
  const rest=cell.getBoundingClientRect().x;
  // focus Ascend via a real click on its bench card, then click slot A
  const card=document.querySelector('.nd-card');
  card.dispatchEvent(new MouseEvent('click',{bubbles:true}));
  await raf();
  const cell2=[...document.querySelectorAll('.nd-row')][0].querySelectorAll('.nd-cell')[0];
  const rest2=cell2.getBoundingClientRect().x;
  cell2.dispatchEvent(new MouseEvent('click',{bubbles:true}));
  const samples=[];
  const cls=[];
  for(let i=0;i<24;i++){ await raf(); const c=[...document.querySelectorAll('.nd-row')][0].querySelectorAll('.nd-cell')[0]; samples.push(Math.round((c.getBoundingClientRect().x-rest2)*100)/100); cls.push(c.className.includes('nd-blocked')?'B':'.'); }
  return JSON.stringify({rest,rest2,offsets:samples,blocked:cls.join(''),denials:E.events.filter(e=>e.type==='socket_denied')});
})()
